import { mkdir, readFile, writeFile } from 'node:fs/promises';

import { compile } from 'json-schema-to-typescript';
import openapiTS, { astToString } from 'openapi-typescript';

const openapiUrl = new URL('../contracts/v1/openapi.yaml', import.meta.url);
const eventSchemaUrl = new URL('../contracts/v1/room-events.schema.json', import.meta.url);
const generatedDir = new URL('../contracts/v1/generated/', import.meta.url);

await mkdir(generatedDir, { recursive: true });

const apiHeader = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;
const apiTypes = apiHeader + astToString(await openapiTS(openapiUrl));
await writeFile(new URL('api.ts', generatedDir), apiTypes);

const eventSchema = JSON.parse(await readFile(eventSchemaUrl, 'utf8'));
const eventTypes = await compile(eventSchema, 'RoomInvalidationEvent', {
  bannerComment: '/* 由 room-events.schema.json 自动生成；请勿直接修改。 */',
  style: { singleQuote: true },
});
await writeFile(new URL('room-events.ts', generatedDir), eventTypes);
